sys_script.script:
(function executeRule(current, previous /*, gs*/ ) {

    var Schedule = current.schedule;

    if (current.settlement_date_2_batch != '') {
        var targetSettlementDate_2 = new MarketBatchProcessUtils();
        var tSD_2 = targetSettlementDate_2.getSettlementDateBatchValue(Schedule, current.settlement_date_2_batch.toString());


        var tSD2 = tSD_2.replace(/(^,)|(,$)/g, '');
        gs.info('MarketBatchProcessUtils Change Timezone : tSD_2 : ' + tSD2);
        //current.setValue('target_settlement_date_2_batch', tSD2);
        current.target_settlement_date_2_batch = tSD2;
    }
	// MSSCUSTODY 5443 - Added else block for empty Settlement Date-2 batch value
	else { 
        current.target_settlement_date_2_batch = '';
    }

    if (current.settlement_date_1_batch != '') {
        var targetSettlementDate_1 = new MarketBatchProcessUtils();
        var tSD_1 = targetSettlementDate_1.getSettlementDateBatchValue(Schedule, current.settlement_date_1_batch.toString());
        gs.info('MarketBatchProcessUtils Change Timezone : tSD_1 : ' + tSD_1);
        current.target_settlement_date_1_batch = tSD_1.toString();
    }
	// MSSCUSTODY 5443 - Added else block for empty Settlement Date-1 batch value
	else {
        current.target_settlement_date_1_batch = '';
    }


    if (current.settlement_date_batch != '') {
        var targetSettlementDate = new MarketBatchProcessUtils();
        var tSD = targetSettlementDate.getSettlementDateBatchValue(Schedule, current.settlement_date_batch.toString());
        gs.info('MarketBatchProcessUtils Change Timezone : tSD : ' + tSD);
        current.target_settlement_date = tSD.toString();
    }
	// MSSCUSTODY 5443 - Added else block for empty Settlement Date batch value
	else {
        current.target_settlement_date = '';
    }
	// MSSCUSTODY-5319 - Added logic for converting the batch time in 'After settlement date batch' and store in 'Target after settlement Date batch' field.
	if (current.after_settlement_date_batch != '') {
        var targetSettlementDateAfter = new MarketBatchProcessUtils();
        var tSDAfter = targetSettlementDateAfter.getSettlementDateBatchValue(Schedule, current.after_settlement_date_batch.toString());
        gs.info('MarketBatchProcessUtils Change Timezone : tSDAfter : ' + tSDAfter);
        current.target_settlement_date_after_batch = tSDAfter.toString();
    }
	else {
        current.target_settlement_date_after_batch = '';
    }


})(current, previous /*, gs*/ );
